"""Build the local static site; all links/assets work on GitHub Pages subpaths."""
from pathlib import Path
import shutil

root = Path(__file__).resolve().parents[1]
site = root / 'website'
(site / 'assets').mkdir(parents=True, exist_ok=True)
shutil.copy2(root / 'assets/grok-128.png', site / 'assets/icon.png')
nav = '<header><a class="logo" href="{base}index.html"><img src="{base}assets/icon.png" alt="">GROK</a><nav aria-label="Main"><a href="{base}index.html#features">Features</a><a href="{base}privacy/index.html">Privacy</a><a href="{base}about/index.html">About</a><a class="small-button" href="{base}download/index.html">Get GROK ↗</a></nav></header>'
footer = '<footer><div><b>GROK</b><p>Graphical Resource Organization Kit<br>Made by akasumitlamba</p></div><div><a href="{base}privacy/index.html">Privacy</a> · <a href="{base}terms/index.html">Terms</a><p>Independent software. Not affiliated with Microsoft, OpenAI, Google or xAI.</p></div></footer>'


def page(title, content, folder=''):
    base = '../' if folder else './'
    target = site / folder
    target.mkdir(parents=True, exist_ok=True)
    (target / 'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="GROK, the independent local-first Windows file sidebar by akasumitlamba."><title>{title} · GROK</title><link rel="icon" href="{base}assets/icon.png"><link rel="stylesheet" href="{base}style.css"></head><body><a class="skip" href="#main">Skip to content</a>{nav.format(base=base)}<main id="main">{content}</main>{footer.format(base=base)}</body></html>''', 'utf-8')


page('Your files. Within reach.', '''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span></span> A QUIET UTILITY FOR WINDOWS</p><h1>Your files.<br>Your AI.<br><em>One sidebar.</em></h1><p class="intro">Your files. Your AI. All in one sidebar.</p><p class="description">Meet GROK — Graphical Resource Organization Kit. A tiny dock at your screen’s right edge. One click opens the files you need. One click gets out of your way.</p><div class="actions"><a class="primary" href="download/index.html">Get GROK for Windows <span>↗</span></a><a href="#features">Take a closer look ↓</a></div><p class="fine">Windows 10 / 11 · Local files · No account required</p></div><div class="product"><div class="product-label"><span>YOUR DESKTOP, WITH ROOM TO THINK</span><span>01 / FILES</span></div><div class="desktop"><div class="desktop-note">Stay in your flow.<br><span>Keep your files close.</span></div><img class="screenshot" src="assets/app-panel.png" alt="Actual GROK application showing its black file panel with compact icon controls and sample folders"><img class="dock-shot" src="assets/app-dock.png" alt="GROK collapsed to a thin dock"></div><p class="caption">Actual application capture with demonstration files.</p></div></section><section class="features" id="features"><div class="section-heading"><p class="eyebrow">SMALL FOOTPRINT. EVERYDAY UTILITY.</p><h2>A place for your files.<br>Not another workspace to manage.</h2></div><div class="feature-grid"><article><span class="number">01</span><h3>Click. Browse. Collapse.</h3><p>A 42-pixel dock expands inward. Choose a narrow, medium or wide panel, or expand into a full-screen workspace with files and chat side by side.</p></article><article><span class="number">02</span><h3>Real files. Real control.</h3><p>Copy, cut, paste, move, rename and recycle. Navigate with paths and breadcrumbs, switch between list and grid, choose visible details, sort, save favorites and filter the current folder.</p></article><article><span class="number">03</span><h3>Move naturally.</h3><p>Drag files into GROK, out to compatible Windows apps, or onto a folder. Transfers run in the background with progress and cancellation.</p></article><article><span class="number">04</span><h3>AI, on your terms.</h3><p>Optional OpenAI, Gemini, xAI, Claude, DeepSeek, Groq, Mistral, OpenRouter and Together AI adapters use your API credentials and chosen model. Review text attachments before sending.</p></article></div></section><section class="privacy-callout"><p class="eyebrow">LOCAL FIRST, BY DESIGN</p><h2>Your file browser<br>doesn’t need the cloud.</h2><div><p>No GROK backend. No mandatory account. No analytics or telemetry. File management works offline.</p><p>When you choose external AI, messages go directly to that provider. You control what you send. Routing services such as OpenRouter forward requests to the chosen upstream provider.</p><a href="privacy/index.html">Read the privacy policy ↗</a></div></section><section class="last"><h2>Quietly useful.<br>Right where you need it.</h2><a class="primary" href="download/index.html">Download & installation ↗</a></section>''')

page('Privacy policy', '''<article class="document"><p class="eyebrow">UPDATED 3 OCTOBER 2026</p><h1>Privacy policy</h1><p class="lead">GROK is an independent Windows application made by akasumitlamba. This policy describes version 1.0.0 and its bundled static website.</p><h2>Local file management</h2><p>Browsing, filename filtering, clipboard operations and file management take place on your computer using your Windows permissions. GROK has no backend, mandatory account, cloud storage, analytics or telemetry. GROK does not upload filenames, documents, clipboard contents, screenshots or search queries as part of ordinary file management. Windows, network drives, sync software and default applications have their own behavior and policies.</p><h2>Settings and credentials</h2><p>Preferences, favorite folder paths, model IDs and default location are saved locally in settings.json under your Windows local app data GROK folder. Packaged Windows may redirect this folder into package data. These settings are not encrypted. API keys are saved separately in Windows Credential Manager for your Windows user. They are never written by GROK to settings, logs or crash reports. Processes running as your user may be able to access user credentials; this is not protection against a compromised computer.</p><h2>Optional external AI</h2><p>AI is disabled by default. When you enable it and press Send, your message and the current conversation are sent directly over HTTPS to OpenAI, Google Gemini or xAI, as selected. A connection test sends a short test message. Requests may incur your provider’s charges. Your key authenticates these requests.</p><p>Selecting files and clicking AI Chat queues them as removable attachments. You can also choose files using Attach. Before sending, you review their content. UTF-8 text files up to 100 KB and folder listings are supported; other formats cannot be sent. The provider receives that text when you send. GROK does not send tools that execute AI suggestions or change files. PDF and Office document extraction is not included.</p><p>Provider handling, retention and account controls apply independently: <a href="https://openai.com/policies/privacy-policy/">OpenAI privacy policy</a>, <a href="https://ai.google.dev/gemini-api/terms">Gemini API terms</a>, and <a href="https://x.ai/legal/privacy-policy">xAI privacy policy</a>. GROK cannot promise that providers retain nothing. It requests no stored Chat Completions where supported; this does not override provider abuse monitoring or other retention.</p><h2>Retention and control</h2><p>Chat and sent attachment text are stored as unencrypted local JSON, separately per provider. History survives provider changes, disabling AI and app restarts. Clear chat deletes the selected provider’s local history. Requests already transmitted cannot be recalled by clearing chat. Settings persist until changed or deleted. Disconnect removes the selected credential from Windows Credential Manager. Remove credentials before uninstalling because they can survive uninstall. Files you create or change are retained at their destinations. Recycled items are managed by Windows.</p><h2>Diagnostics</h2><p>GROK creates no application telemetry, request logs or crash-report uploads. Windows and security software may collect their own diagnostics, memory dumps or network information.</p><h2>Website</h2><p>This site is static, with bundled images and system fonts. It sets no cookies, uses no analytics and has no forms or accounts. Opening external links contacts those sites. If the site is deployed, the chosen hosting service may process IP addresses and ordinary request logs under its own policy; no public host is configured in this local build.</p><h2>Developer and changes</h2><p>Developer: akasumitlamba. No support email or verified contact URL has been supplied, so none is invented here. Use the distribution channel through which you obtained GROK for support. Policy changes will update this page and its effective date. No certification or legal compliance evaluation is claimed.</p></article>''', 'privacy')

page('Terms of use', '''<article class="document"><p class="eyebrow">GROK 1.0.0</p><h1>Terms of use</h1><p class="lead">GROK is independent software made by akasumitlamba. It is not an official product of Microsoft, OpenAI, Google or xAI.</p><h2>Your files and actions</h2><p>File operations follow your actions and Windows permissions. Keep backups of important data. Check destinations and selections before moving, renaming or deleting items. Some drives cannot recycle deleted files. Canceled or failed multi-item operations may leave completed items at the destination; inspect the results before retrying.</p><h2>External AI services</h2><p>You are responsible for your API credentials, provider account, usage charges, model access and the information you choose to send. Only send content you are authorized to share. Provider terms apply separately. GROK does not guarantee provider availability, output accuracy or retention behavior. AI suggestions do not execute file operations automatically.</p><h2>Software availability</h2><p>The software is provided as available, without a promise of uninterrupted or error-free operation. This text does not limit rights that cannot be limited under applicable law. This build is subject to the validation limits described on the download page.</p><h2>Third-party components</h2><p>Third-party software licenses remain applicable. Python and Qt/PySide notices accompany the package. These terms do not restrict rights granted under those licenses, including rights needed to debug modified LGPL components.</p></article>''', 'terms')

page('About', '''<article class="document"><p class="eyebrow">MADE BY AKASUMITLAMBA</p><h1>A small utility.<br>A clear purpose.</h1><p class="lead">GROK stands for Graphical Resource Organization Kit — accessing and organizing resources through a graphical desktop interface.</p><h2>Files come first</h2><p>A compact right-edge dock keeps Windows files within reach. The application remains useful offline, without enabling AI or creating an account.</p><h2>Why GROK?</h2><p>The name describes the file utility. Optional integrations let you connect independent AI services from the same panel. GROK is not the official Grok service from xAI and is not affiliated with any provider.</p><h2>Built for Windows</h2><p>Python and PySide6 provide the desktop interface. Windows supplies credential storage, file associations, clipboard integration and shell properties. Version 1.0.0 targets Windows 10 build 19041 or later, and Windows 11, on x64.</p></article>''', 'about')

page('Download', '''<article class="document"><p class="eyebrow">WINDOWS X64 · VERSION 1.0.0</p><h1>Get GROK.</h1><p class="lead">Your files. Your AI. All in one sidebar.</p><p>This local project includes an executable distribution and an MSIX package. No public download release has been published.</p><a class="primary" href="GROK.msix" download>Download local MSIX ↗</a><p class="fine">The build process copies the generated package here. A development package requires certificate trust; an unsigned package cannot be installed normally.</p><h2>Install</h2><ol><li>Read the supplied installation guide and verify the package checksum.</li><li>For a signed development package, trust only the supplied development certificate on a test machine you control.</li><li>Open GROK.msix with Windows App Installer, or use Add-AppxPackage after certificate trust is configured.</li><li>Launch GROK from Start. Click the dock, or use Ctrl+Alt+G.</li></ol><h2>Validation limits</h2><p>See the project’s QA report for the exact executed checks. Live provider calls require your API account and are not certified by fixture tests. Physical monitor reconnection, every DPI/taskbar combination, network drives and Windows drag/drop interoperability need testing on your target setup.</p><h2>Portable alternative</h2><p>The project also produces dist/GROK/GROK.exe. Keep its accompanying _internal folder beside it. The portable build does not require MSIX certificate trust.</p></article>''', 'download')
